// src/fn/son.ts
import { z as z76 } from "zod";
import { length as length66 } from "circuit-json";
var son_def = base_def.extend({
  fn: z76.string(),
  num_pins: z76.union([z76.literal(6), z76.literal(8)]).default(8),
  w: z76.string().default("3mm"),
  h: z76.string().default("3mm"),
  p: z76.string().default("0.5mm"),
  pl: z76.string().default("0.52mm"),
  pw: z76.string().default("0.35mm"),
  epw: z76.string().default("1.40mm"),
  eph: z76.string().default("1.60mm"),
  string: z76.string().optional(),
  ep: z76.boolean().default(false)
});
var son = (raw_params) => {
  if (raw_params.string && raw_params.string.includes("_ep")) {
    raw_params.ep = true;
  }
  const match = raw_params.string?.match(/^son_(\d+)/);
  const numPins = match ? Number.parseInt(match[1], 10) : raw_params.num_pins || 8;
  const parameters = son_def.parse({
    ...raw_params,
    num_pins: numPins
  });
  const w = length66.parse(parameters.w);
  const h = length66.parse(parameters.h);
  const p = length66.parse(parameters.p);
  const pl = length66.parse(parameters.pl);
  const pw = length66.parse(parameters.pw);
  const epw = length66.parse(parameters.epw);
  const eph = length66.parse(parameters.eph);
  const cornerRadius = Math.min(pl, pw) / 8;
  const pads = [];
  for (let i = 0; i < parameters.num_pins; i++) {
    const { x, y } = getSonPadCoord(parameters.num_pins, i + 1, w, p);
    pads.push(rectpad(i + 1, x, y, pl, pw, cornerRadius));
  }
  if (parameters.ep) {
    pads.push(rectpad(parameters.num_pins + 1, 0, 0, epw, eph));
  }
  const silkscreenBoxWidth = w;
  const silkscreenBoxHeight = h;
  const silkscreenTopLine = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: [
      { x: -silkscreenBoxWidth / 2, y: silkscreenBoxHeight / 2 },
      { x: silkscreenBoxWidth / 2, y: silkscreenBoxHeight / 2 }
    ],
    stroke_width: 0.05,
    pcb_silkscreen_path_id: ""
  };
  const silkscreenBottomLine = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: [
      { x: -silkscreenBoxWidth / 2, y: -silkscreenBoxHeight / 2 },
      { x: silkscreenBoxWidth / 2, y: -silkscreenBoxHeight / 2 }
    ],
    stroke_width: 0.05,
    pcb_silkscreen_path_id: ""
  };
  const pin1Position = getSonPadCoord(
    parameters.num_pins,
    1,
    silkscreenBoxWidth,
    p
  );
  const pin1MarkerPosition = {
    x: pin1Position.x - 0.4,
    y: pin1Position.y
  };
  const pin1Marking = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "pin_marker_1",
    route: [
      { x: pin1MarkerPosition.x - 0.4, y: pin1MarkerPosition.y },
      { x: pin1MarkerPosition.x - 0.7, y: pin1MarkerPosition.y + 0.3 },
      { x: pin1MarkerPosition.x - 0.7, y: pin1MarkerPosition.y - 0.3 },
      { x: pin1MarkerPosition.x - 0.4, y: pin1MarkerPosition.y }
    ],
    stroke_width: 0.05,
    pcb_silkscreen_path_id: "pin_marker_1"
  };
  const silkscreenRefText = silkscreenRef(
    0,
    silkscreenBoxHeight / 2 + 0.5,
    0.3
  );
  const pinColumnCenterX = Math.abs(
    getSonPadCoord(parameters.num_pins, 1, w, p).x
  );
  const pinRowSpanY = (parameters.num_pins / 2 - 1) * p + pw;
  const pinRowSpanX = pinColumnCenterX * 2 + pl;
  const courtyardStepInnerHalfWidth = w / 2 + 0.25;
  const courtyardStepOuterHalfWidth = pinRowSpanX / 2 + 0.25;
  const courtyardStepInnerHalfHeight = pinRowSpanY / 2 + 0.25;
  const courtyardStepOuterHalfHeight = h / 2 + 0.25;
  const courtyard = {
    type: "pcb_courtyard_outline",
    pcb_courtyard_outline_id: "",
    pcb_component_id: "",
    layer: "top",
    outline: createRectUnionOutline([
      {
        minX: -courtyardStepOuterHalfWidth,
        maxX: courtyardStepOuterHalfWidth,
        minY: -courtyardStepInnerHalfHeight,
        maxY: courtyardStepInnerHalfHeight
      },
      {
        minX: -courtyardStepInnerHalfWidth,
        maxX: courtyardStepInnerHalfWidth,
        minY: -courtyardStepOuterHalfHeight,
        maxY: courtyardStepOuterHalfHeight
      }
    ])
  };
  return {
    circuitJson: [
      ...pads,
      silkscreenTopLine,
      silkscreenBottomLine,
      silkscreenRefText,
      pin1Marking,
      courtyard
    ],
    parameters
  };
};
var getSonPadCoord = (num_pins, pn, w, p) => {
  const half = num_pins / 2;
  const rowIndex = (pn - 1) % half;
  const col = pn <= half ? -1 : 1;
  const row = (half - 1) / 2 - rowIndex;
  return {
    x: col * length66.parse("1.4mm"),
    y: row * p
  };
};

// src/fn/vson.ts
import { z as z77 } from "zod";
import { length as length67, distance as distance3 } from "circuit-json";
var vson_def = base_def.extend({
  fn: z77.string(),
  num_pins: z77.number().optional().default(8),
  p: distance3.describe("pitch (distance between center of each pin)"),
  w: length67.describe("width between vertical rows of pins"),
  grid: dim2d.describe("width and height of the border of the footprint"),
  ep: dim2d.default("0x0mm").describe("width and height of the central exposed thermal pad"),
  epx: length67.default("0mm").describe("x offset of the center of the central exposed thermal pad"),
  pinw: length67.describe("width of the pin pads"),
  pinh: length67.describe("height of the pin pads")
});
var vson = (raw_params) => {
  const parameters = vson_def.parse(raw_params);
  const { num_pins, p, w, grid: grid2, ep, epx, pinw, pinh } = parameters;
  if (num_pins % 2 !== 0) {
    throw new Error("invalid number of pins");
  }
  const pads = [];
  const cornerRadius = Math.min(pinw, pinh) / 8;
  for (let i = 0; i < num_pins; i++) {
    const { pinX, pinY } = getCcwVsonCoords({
      pinCount: num_pins,
      pinIndex: i,
      width: w,
      pitch: p
    });
    pads.push(rectpad(i + 1, pinX, pinY, pinw, pinh, cornerRadius));
  }
  if (ep.x > 0 && ep.y > 0) {
    pads.push(rectpad(parameters.num_pins + 1, epx, 0, ep.x, ep.y));
  }
  const silkscreenPaths = getSilkscreenPaths(grid2);
  const silkscreenRefText = silkscreenRef(
    0,
    grid2.y / 2 + p,
    grid2.y / 6
  );
  const pinRowSpanY = (num_pins / 2 - 1) * p + pinh;
  const pinRowSpanX = w + pinw;
  const courtyardStepInnerHalfWidth = grid2.x / 2 + 0.25;
  const courtyardStepOuterHalfWidth = pinRowSpanX / 2 + 0.25;
  const pinRowCourtyardHalfY = pinRowSpanY / 2 + 0.25;
  const pinRowExtendedCourtyardHalfY = pinRowSpanY / 2 + 0.45 + Math.max(0, 0.8 - p);
  const courtyardStepOuterHalfHeight = Math.min(
    grid2.y / 2 + 0.25,
    pinRowExtendedCourtyardHalfY
  );
  const courtyardStepNotchDepthY = Math.max(
    0,
    0.37 - Math.max(
      0,
      courtyardStepOuterHalfWidth - courtyardStepInnerHalfWidth - 0.38
    ) * 1.4
  );
  const courtyardStepInnerHalfHeight = Math.max(
    pinRowCourtyardHalfY,
    courtyardStepOuterHalfHeight - courtyardStepNotchDepthY
  );
  const courtyard = {
    type: "pcb_courtyard_outline",
    pcb_courtyard_outline_id: "",
    pcb_component_id: "",
    layer: "top",
    outline: createRectUnionOutline([
      {
        minX: -courtyardStepOuterHalfWidth,
        maxX: courtyardStepOuterHalfWidth,
        minY: -courtyardStepInnerHalfHeight,
        maxY: courtyardStepInnerHalfHeight
      },
      {
        minX: -courtyardStepInnerHalfWidth,
        maxX: courtyardStepInnerHalfWidth,
        minY: -courtyardStepOuterHalfHeight,
        maxY: courtyardStepOuterHalfHeight
      }
    ])
  };
  return {
    circuitJson: [...pads, ...silkscreenPaths, silkscreenRefText, courtyard],
    parameters
  };
};
var getCcwVsonCoords = (params) => {
  let pinY = 0;
  let pinX = 0;
  const centerY = (params.pinCount / 2 - 1) * params.pitch / 2;
  const pinHalf = params.pinCount / 2;
  if (params.pinIndex + 1 <= pinHalf) {
    pinY = params.pitch * params.pinIndex - centerY;
    pinX = 0 - params.width / 2;
  } else {
    pinY = params.pitch * (params.pinCount - params.pinIndex - 1) - centerY;
    pinX = params.width / 2;
  }
  return { pinX, pinY };
};
var getSilkscreenPaths = (grid2) => {
  const borderMargin = 0.1;
  const cornerLine = grid2.y / 30;
  const silkscreenPaths = [
    // top silkscreen path
    {
      layer: "top",
      pcb_component_id: "",
      pcb_silkscreen_path_id: "",
      type: "pcb_silkscreen_path",
      route: [
        {
          x: -grid2.x / 2 - borderMargin,
          y: grid2.y / 2 + borderMargin - cornerLine
        },
        {
          x: -grid2.x / 2 - borderMargin,
          y: grid2.y / 2 + borderMargin
        },
        {
          x: grid2.x / 2 + borderMargin,
          y: grid2.y / 2 + borderMargin
        },
        {
          x: grid2.x / 2 + borderMargin,
          y: grid2.y / 2 + borderMargin - cornerLine
        }
      ],
      stroke_width: grid2.y / 30
    },
    // bottom silkscreen path
    {
      layer: "top",
      pcb_component_id: "",
      pcb_silkscreen_path_id: "",
      type: "pcb_silkscreen_path",
      route: [
        {
          x: -grid2.x / 2 - borderMargin,
          y: -grid2.y / 2 - borderMargin + cornerLine
        },
        {
          x: -grid2.x / 2 - borderMargin,
          y: -grid2.y / 2 - borderMargin
        },
        {
          x: grid2.x / 2 + borderMargin,
          y: -grid2.y / 2 - borderMargin
        },
        {
          x: grid2.x / 2 + borderMargin,
          y: -grid2.y / 2 - borderMargin + cornerLine
        }
      ],
      stroke_width: grid2.y / 30
    }
  ];
  return silkscreenPaths;
};

// src/fn/wson.ts
import {
  length as length68
} from "circuit-json";
import { z as z78 } from "zod";
var wson_def = base_def.extend({
  fn: z78.literal("wson"),
  num_pins: z78.literal(8).default(8),
  p: length68.default("0.5mm").describe("pin pitch"),
  rowspan: length68.default("3.015mm").describe("distance between pad rows"),
  pl: length68.default("0.6mm").describe("pad length across the package edge"),
  pw: length68.default("0.28mm").describe("pad width along the pin row"),
  ep: z78.boolean().default(true).describe("include the exposed pad"),
  epw: length68.default("1.7mm").describe("exposed pad width"),
  eph: length68.default("0.3mm").describe("exposed pad height"),
  w: length68.default("2mm").describe("package body width"),
  h: length68.default("3mm").describe("package body height")
});
var wson = (rawParams) => {
  const parameters = wson_def.parse(rawParams);
  const { p, rowspan, pl, pw, ep, epw, eph, w, h } = parameters;
  const pads = [];
  const startX = -3 * p / 2;
  for (let index = 0; index < 4; index += 1) {
    const x = startX + index * p;
    pads.push(rectpad(index + 1, x, -rowspan / 2, pw, pl));
    pads.push(rectpad(8 - index, x, rowspan / 2, pw, pl));
  }
  if (ep) pads.push(rectpad(9, 0, 0, epw, eph));
  const silkscreen = [
    silkscreenpath([
      { x: -w / 2, y: -h / 2 },
      { x: -w / 2, y: h / 2 }
    ]),
    silkscreenpath([
      { x: w / 2, y: -h / 2 },
      { x: w / 2, y: h / 2 }
    ])
  ];
  const ref = silkscreenRef(
    0,
    Math.max(h / 2, (rowspan + pl) / 2) + 0.6,
    0.5
  );
  const copperWidth = Math.max(3 * p + pw, ep ? epw : 0);
  const copperHeight = Math.max(rowspan + pl, ep ? eph : 0);
  const courtyard = {
    type: "pcb_courtyard_rect",
    pcb_courtyard_rect_id: "",
    pcb_component_id: "",
    center: { x: 0, y: 0 },
    width: Math.max(w, copperWidth) + 0.5,
    height: Math.max(h, copperHeight) + 0.5,
    layer: "top"
  };
  return {
    circuitJson: [...pads, ...silkscreen, ref, courtyard],
    parameters
  };
};

// src/fn/solderjumper.ts
import { length as length69 } from "circuit-json";
var solderjumper = (params) => {
  const { num_pins, bridged, p = 2.54, pw = 1.5, ph = 1.5 } = params;
  const padSpacing7 = length69.parse(p);
  const padWidth = length69.parse(pw);
  const padHeight = length69.parse(ph);
  const traceWidth = Math.min(padHeight / 4, 0.5);
  const pads = [];
  for (let i = 0; i < num_pins; i++) {
    pads.push(rectpad(i + 1, i * padSpacing7, 0, padWidth, padHeight));
  }
  let traces = [];
  if (bridged) {
    const pins = bridged.split("").map(Number);
    if (pins.length > 1) {
      for (let i = 0; i < pins.length - 1; i++) {
        const from = pins[i];
        const to = pins[i + 1];
        if (typeof from === "number" && typeof to === "number" && !isNaN(from) && !isNaN(to)) {
          const xCenterFrom = (from - 1) * padSpacing7;
          const xCenterTo = (to - 1) * padSpacing7;
          const directionMult = Math.sign(xCenterTo - xCenterFrom);
          const x1 = xCenterFrom + directionMult * (padWidth / 2);
          const x2 = xCenterTo - directionMult * (padWidth / 2);
          traces.push({
            type: "pcb_trace",
            pcb_trace_id: "",
            route: [
              {
                start_pcb_port_id: `{PIN${from}}`,
                x: x1,
                y: 0,
                width: traceWidth,
                layer: "top",
                route_type: "wire"
              },
              {
                end_pcb_port_id: `{PIN${to}}`,
                x: x2,
                y: 0,
                width: traceWidth,
                layer: "top",
                route_type: "wire"
              }
            ]
          });
        }
      }
    }
  }
  const outlineWidth = (num_pins - 1) * padSpacing7 + padWidth + 0.7;
  const outlineHeight = padHeight + 1;
  const outlineCenterX = (num_pins - 1) * padSpacing7 / 2;
  const outlineCenterY = 0;
  const silkscreenRect = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    pcb_silkscreen_path_id: "outline",
    route: [
      {
        x: outlineCenterX - outlineWidth / 2,
        y: outlineCenterY - outlineHeight / 2
      },
      {
        x: outlineCenterX + outlineWidth / 2,
        y: outlineCenterY - outlineHeight / 2
      },
      {
        x: outlineCenterX + outlineWidth / 2,
        y: outlineCenterY + outlineHeight / 2
      },
      {
        x: outlineCenterX - outlineWidth / 2,
        y: outlineCenterY + outlineHeight / 2
      },
      {
        x: outlineCenterX - outlineWidth / 2,
        y: outlineCenterY - outlineHeight / 2
      }
    ],
    stroke_width: 0.15
  };
  const refOffset = 0.6;
  const refY = outlineCenterY + outlineHeight / 2 + refOffset;
  const silk = silkscreenRef(outlineCenterX, refY, 0.4);
  const pinRowSpanX = (num_pins - 1) * padSpacing7;
  const padOuterHalfWidth = pinRowSpanX / 2 + padWidth / 2;
  const padOuterHalfHeight = padHeight / 2;
  const courtyardHalfWidth = padOuterHalfWidth + 0.5;
  const courtyardHalfHeight = padOuterHalfHeight + 0.5;
  const courtyard = {
    type: "pcb_courtyard_rect",
    pcb_courtyard_rect_id: "",
    pcb_component_id: "",
    center: { x: pinRowSpanX / 2, y: 0 },
    width: 2 * courtyardHalfWidth,
    height: 2 * courtyardHalfHeight,
    layer: "top"
  };
  return {
    circuitJson: [...pads, ...traces, silkscreenRect, silk, courtyard],
    parameters: params
  };
};

// src/fn/sot457.ts
