// src/fn/electrolytic.ts
import {
  length as length71
} from "circuit-json";
import { z as z82 } from "zod";
var electrolytic_def = base_def.extend({
  fn: z82.string(),
  p: length71.optional().default("7.5mm"),
  id: length71.optional().default("1mm"),
  od: length71.optional().default("2mm"),
  d: length71.optional().default("10.5mm")
});
var generate_circle_arcs = (centerX, centerY, radius, cut, cutHeight) => {
  const topArc = [];
  const bottomArc = [];
  for (let i = 0; i <= 50; i++) {
    const theta = i / 50 * Math.PI;
    const x = centerX + Math.cos(theta) * radius;
    const y = centerY + Math.sin(theta) * radius;
    if (x < centerX - cut && y >= centerY - cutHeight / 2 && y <= centerY + cutHeight / 2) {
      continue;
    }
    topArc.push({ x, y });
  }
  for (let i = 0; i <= 50; i++) {
    const theta = Math.PI + i / 50 * Math.PI;
    const x = centerX + Math.cos(theta) * radius;
    const y = centerY + Math.sin(theta) * radius;
    if (x < centerX - cut && y >= centerY - cutHeight / 2 && y <= centerY + cutHeight / 2) {
      continue;
    }
    bottomArc.push({ x, y });
  }
  return { topArc, bottomArc };
};
var electrolytic = (raw_params) => {
  const parameters = electrolytic_def.parse(raw_params);
  const { p, id, od, d } = parameters;
  const plated_holes = [
    platedHoleWithRectPad({
      pn: 1,
      x: -p / 2,
      y: 0,
      holeDiameter: id,
      rectPadWidth: od,
      rectPadHeight: od
    }),
    platedhole(2, p / 2, 0, id, od)
  ];
  const { topArc, bottomArc } = generate_circle_arcs(
    0,
    0,
    d / 2 + 0.1,
    od / 2,
    od
  );
  const silkscreenBody2 = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: topArc,
    stroke_width: 0.1,
    pcb_silkscreen_path_id: ""
  };
  const silkscreenBody3 = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: bottomArc,
    stroke_width: 0.1,
    pcb_silkscreen_path_id: ""
  };
  const silkscreenBody = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: [
      { x: 0, y: d / 2 + 0.1 },
      { x: 0, y: -(d / 2 + 0.1) }
    ],
    stroke_width: 0.1,
    pcb_silkscreen_path_id: ""
  };
  const X = -(d / 2 + 0.5);
  const plusY = od / 2 + 1.5;
  const Size = 0.5;
  const silkscreenpath2 = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: [
      { x: X - Size, y: plusY },
      { x: X + Size, y: plusY }
    ],
    stroke_width: 0.1,
    pcb_silkscreen_path_id: ""
  };
  const silkscreenline = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    route: [
      { x: X, y: plusY - Size },
      { x: X, y: plusY + Size }
    ],
    stroke_width: 0.1,
    pcb_silkscreen_path_id: ""
  };
  const silkscreenRefText = silkscreenRef(0, d / 2 + 1, 0.5);
  const bodyOuterRadius = d / 2;
  const pinOuterRadius = p / 2 + od / 2;
  const courtyardClearance = 0.25;
  const courtyardRadius = Math.max(bodyOuterRadius, pinOuterRadius) + courtyardClearance;
  const courtyard = {
    type: "pcb_courtyard_circle",
    pcb_courtyard_circle_id: "",
    pcb_component_id: "",
    center: { x: 0, y: 0 },
    radius: courtyardRadius,
    layer: "top"
  };
  return {
    circuitJson: [
      ...plated_holes,
      silkscreenBody2,
      silkscreenBody3,
      silkscreenBody,
      silkscreenpath2,
      silkscreenline,
      silkscreenRefText,
      courtyard
    ],
    parameters
  };
};

// src/fn/fpc.ts
import {
  length as length72
} from "circuit-json";
import { z as z83 } from "zod";
var fpc_def = base_def.extend({
  fn: z83.literal("fpc"),
  num_pins: z83.coerce.number().int().min(2),
  p: length72.default("0.5mm").describe("contact pad pitch"),
  pw: length72.default("0.3mm").describe("contact pad width"),
  pl: length72.default("1.25mm").describe("contact pad length"),
  staggered: z83.boolean().default(false).describe("alternate contacts between two rows"),
  reverse: z83.boolean().default(false).describe("place pin 1 on the upper row when staggered"),
  py: length72.default("2.4mm").describe("staggered row center pitch"),
  toppl: length72.optional().describe("upper-row contact pad length"),
  bottompl: length72.optional().describe("lower-row contact pad length"),
  mpx: length72.optional().describe("mounting pad center pitch"),
  mpy: length72.optional().describe("mounting pad row distance from the contact-row center"),
  mounttop: z83.boolean().default(false).describe("place the mounting pads above the contact-row center"),
  mpw: length72.default("2mm").describe("mounting pad width"),
  mpl: length72.default("2.5mm").describe("mounting pad length")
});
var rectangularPad = (...parameters) => rectpad(...parameters);
var getPadBounds = (pads) => ({
  maxX: Math.max(...pads.map((pad2) => pad2.x + pad2.width / 2)),
  maxY: Math.max(...pads.map((pad2) => pad2.y + pad2.height / 2)),
  minX: Math.min(...pads.map((pad2) => pad2.x - pad2.width / 2)),
  minY: Math.min(...pads.map((pad2) => pad2.y - pad2.height / 2))
});
var fpc = (rawParams) => {
  const parsedParameters = fpc_def.parse(rawParams);
  const {
    num_pins: numPins,
    p,
    pw,
    pl,
    staggered,
    reverse,
    py,
    toppl,
    bottompl,
    mounttop,
    mpw,
    mpl
  } = parsedParameters;
  const contactSpan = (numPins - 1) * p;
  const mpx = parsedParameters.mpx ?? contactSpan + (staggered ? 3.5 : 3.38);
  const mpy = parsedParameters.mpy ?? (staggered ? 0 : 2.575);
  const mountY = mpy === 0 ? 0 : (mounttop ? 1 : -1) * mpy;
  const startX = -contactSpan / 2;
  const contactPads = Array.from({ length: numPins }, (_, index) => {
    const isUpperRow = staggered && index % 2 === 1 !== reverse;
    const y = staggered ? isUpperRow ? py / 2 : -py / 2 : 0;
    const padLength = isUpperRow ? toppl ?? pl : bottompl ?? pl;
    return rectangularPad(index + 1, startX + index * p, y, pw, padLength);
  });
  const mountingPads = [
    rectangularPad(numPins + 1, mpx / 2, mountY, mpw, mpl),
    rectangularPad(numPins + 2, -mpx / 2, mountY, mpw, mpl)
  ];
  const pads = [...contactPads, ...mountingPads];
  const bounds = getPadBounds(pads);
  const silkInsetX = Math.min(contactSpan / 2 + pw / 2, mpx / 2 - mpw / 2);
  const topSilkY = bounds.maxY + 0.2;
  const bottomSilkY = bounds.minY - 0.2;
  const pinOne = contactPads[0];
  const pinMarkerX = pinOne.x - pinOne.width / 2 - 0.2;
  const pinMarkerY = pinOne.y;
  const silkscreen = [
    silkscreenpath([
      { x: -silkInsetX, y: topSilkY },
      { x: silkInsetX, y: topSilkY }
    ]),
    silkscreenpath([
      { x: -silkInsetX, y: bottomSilkY },
      { x: silkInsetX, y: bottomSilkY }
    ]),
    silkscreenpath([
      { x: pinMarkerX - 0.25, y: pinMarkerY - 0.25 },
      { x: pinMarkerX, y: pinMarkerY },
      { x: pinMarkerX - 0.25, y: pinMarkerY + 0.25 }
    ])
  ];
  const ref = silkscreenRef(0, topSilkY + 0.7, 0.5);
  const courtyard = {
    type: "pcb_courtyard_rect",
    pcb_courtyard_rect_id: "",
    pcb_component_id: "",
    center: {
      x: (bounds.minX + bounds.maxX) / 2,
      y: (bounds.minY + bounds.maxY) / 2
    },
    width: bounds.maxX - bounds.minX + 0.5,
    height: bounds.maxY - bounds.minY + 0.5,
    layer: "top"
  };
  return {
    circuitJson: [...pads, ...silkscreen, ref, courtyard],
    parameters: {
      ...parsedParameters,
      mpx,
      mpy,
      toppl: toppl ?? pl,
      bottompl: bottompl ?? pl
    }
  };
};

