  const courtyardStepOuterHalfWidth = pinToeHalfSpanX + 0.25;
  const courtyardStepInnerHalfHeight = pinRowSpanY / 2 + 0.25;
  const courtyardStepOuterHalfHeight = courtyardStepInnerHalfHeight + 0.2;
