// src/fn/sot143.ts
import { length as length80 } from "circuit-json";
import { z as z93 } from "zod";
var sot143_def = base_def.extend({
  fn: z93.literal("sot143"),
  num_pins: z93.literal(4).default(4),
  p: length80.default("2.382774mm"),
  px: length80.default("1.89992mm"),
  pw: length80.default("0.8382mm"),
  ph: length80.default("0.8382mm"),
  pin1padwidth: length80.default("1.1938mm"),
  pin1centeroffsetx: length80.default("0.199898mm"),
  w: length80.default("3mm"),
  h: length80.default("2.9mm")
});
var sot143 = (rawParams) => {
  const parameters = sot143_def.parse(rawParams);
  const { p, px, pw, ph, pin1padwidth, pin1centeroffsetx, w, h } = parameters;
  const halfX = px / 2;
  const halfY = p / 2;
  const pads = [
    rectpad(1, -halfX + pin1centeroffsetx, -halfY, pin1padwidth, ph),
    rectpad(2, halfX, -halfY, pw, ph),
    rectpad(3, halfX, halfY, pw, ph),
    rectpad(4, -halfX, halfY, pw, ph)
  ];
  const halfWidth = w / 2;
  const halfHeight = h / 2;
  const silkscreen = [
    silkscreenpath([
      { x: -halfWidth, y: -halfHeight / 2 },
      { x: -halfWidth, y: halfHeight / 2 }
    ]),
    silkscreenpath([
      { x: halfWidth, y: halfHeight / 2 },
      { x: halfWidth, y: -halfHeight / 2 }
    ])
  ];
  const copperWidth = px + Math.max(pin1padwidth, pw);
  const copperHeight = p + ph;
  const courtyard = {
    type: "pcb_courtyard_rect",
    pcb_courtyard_rect_id: "",
    pcb_component_id: "",
    center: { x: 0, y: 0 },
    width: Math.max(w, copperWidth) + 0.5,
    height: Math.max(h, copperHeight) + 0.5,
    layer: "top"
  };
  return {
    circuitJson: [
      ...pads,
      ...silkscreen,
      silkscreenRef(0, Math.max(halfHeight, copperHeight / 2) + 0.8, 0.4),
      courtyard
    ],
    parameters
  };
};

